pre=r'''% !TeX program = xelatex
% Самостоятельный сводный файл. Составлен из tex_результат/1/1.tex ... tex_результат/12/12.tex.
% Материал ответов встроен; \input отдельных ответов не требуется.
\documentclass[12pt,a4paper]{article}
\usepackage{fontspec}
\setmainfont{Times New Roman}
\usepackage[english,russian]{babel}
\usepackage{amsmath,amssymb,mathrsfs,cancel}
\usepackage[margin=22mm]{geometry}
\usepackage{graphicx,float}
\usepackage[unicode,hidelinks]{hyperref}
\DeclareMathOperator{\grad}{grad}
\DeclareMathOperator{\Div}{div}
\newcommand{\Rey}{\mathrm{Re}}
\newcommand{\topic}[1]{\par\medskip\noindent\textbf{#1}\par\nobreak\smallskip}
\newenvironment{textquote}{\begin{quote}\sloppy}{\end{quote}}
\setlength{\emergencystretch}{3em}
\setlength{\parindent}{0pt}
\interfootnotelinepenalty=10000
\sloppy
\newcounter{questionnumber}
\renewcommand{\theHequation}{q\arabic{questionnumber}.\arabic{equation}}
\renewcommand{\thefootnote}{\arabic{footnote})}
\hypersetup{pdftitle={Течения в пористых средах. Вопросы 1–12}}
\begin{document}
\begin{center}
{\LARGE\bfseries Течения в пористых средах\par}
\medskip
{\Large Вопросы 1--12\par}
\end{center}
\noindent К каждому вопросу приведены краткий указатель источников, план рассказа и материал из соответствующего TeX-ответа. Определения, формулы, условия применимости и выводы сохранены из ответов; план служит для навигации. Номера формул относятся к исходным книгам. Отмеченные в ответах неопределённости сохранены.
\tableofcontents
'''
parts=[pre];counts=[]
for n in range(1,13):
 path=root/f'tex_результат/{n}/{n}.tex';raw=path.read_text(encoding='utf-8');preamble,doc=raw.split(r'\begin{document}',1);doc=doc.split(r'\end{document}',1)[0]
 question=re.search(r'\\section\*\{Вопрос \d+\}\s*(.*?)\s*\\medskip',doc,re.S)[1].strip();question=re.sub(r'^\\noindent\s*','',question)
 content=doc.split(r'\par\bigskip',1)[1].strip();content=content.replace('% END QUESTION HEADER','')
 # Every original image path is resolved from the new master document's folder.
 content=re.sub(r'(\\includegraphics(?:\[[^\]]*\])?\{)figures/',rf'\g<1>tex_результат/{n}/figures/',content)
 content=content.replace(r'\clearpage\section*{Отдельный фрагмент конспекта: труба-источник}',r'\clearpage\subsection*{Отдельный фрагмент конспекта: труба-источник}')
 source_defs='\n'.join(line for line in preamble.splitlines() if line.startswith(r'\newcommand{\source}'))
 section=f'\\clearpage\n\\setcounter{{questionnumber}}{{{n}}}\n\\setcounter{{equation}}{{0}}\n\\setcounter{{footnote}}{{0}}\n\\phantomsection\n\\section*{{Вопрос {n}. {short[n]}}}\n\\addcontentsline{{toc}}{{section}}{{Вопрос {n}. {short[n]}}}\n'
 header='\\textbf{Формулировка вопроса.} '+question+'\n\n\\medskip\n\\textbf{Где найти.} '+where[n]+'\n\n'
 outline='\\subsection*{Что рассказать}\n\\begin{enumerate}\n'+''.join('\\item '+x+'\n' for x in plans[n])+'\\end{enumerate}\n'
 material='\\subsection*{Определения, утверждения, формулы и выводы}\n'+f'% Исходный ответ: tex_результат/{n}/{n}.tex\n'+'\\begingroup\n'+source_defs+'\n'+content+'\n\\endgroup\n'
 parts.append(section+header+outline+material)
 counts.append(dict(question=n,quotes=len(re.findall(r'\\begin\{(?:quote|textquote)\}',content)),tags=re.findall(r'\\tag\{([^}]+)',content)))
parts.append('\\end{document}\n')
target=root/'porous_all_questions.tex';target.write_text('\n'.join(parts),encoding='utf-8')
(root/'tex/build_all_questions_manifest.json').write_text(json.dumps(counts,ensure_ascii=False,indent=2),encoding='utf-8')
print(target)
print('questions',len(counts),'quotes',sum(x['quotes'] for x in counts),'equations',sum(len(x['tags']) for x in counts))
# Check all original equation labels and body contents survive the combination.
master=target.read_text(encoding='utf-8');labels=re.findall(r'\\label\{([^}]+)',master);assert len(labels)==len(set(labels)), 'duplicate labels'
for n in range(1,13):
 raw=(root/f'tex_результат/{n}/{n}.tex').read_text(encoding='utf-8');assert re.findall(r'\\tag\{([^}]+)',raw)==counts[n-1]['tags']
for f in re.findall(r'\\includegraphics(?:\[[^\]]*\])?\{([^}]+)',master):assert (root/f).exists(),f
print('Labels, formula numbers and images verified')
